// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchmarkResult) predicate.BenchmarkResult {
	return predicate.BenchmarkResult(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchmarkResult) predicate.BenchmarkResult {
	return predicate.BenchmarkResult(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchmarkResult) predicate.BenchmarkResult {
	return predicate.BenchmarkResult(sql.NotPredicates(p))
}
